//! icon data and the `<Icon>` component
//!
//! each icon is a `const` generated by `cargo xtask icons` from the upstream
//! package at a pinned version, so unused icons are dead code the linker drops
//!
//! ```ignore
//! use leptos_kit_icons::{Icon, lucide};
//!
//! view! { <Icon icon=lucide::CHEVRON_DOWN class="size-4" /> }
//! ```
//!
//! [`semantic`] holds the icons leptos-kit uses itself, named by where they are
//! used; which library draws them is a cargo feature

mod icon;

#[cfg(feature = "hugeicons")]
pub mod hugeicons;
#[cfg(feature = "lucide")]
pub mod lucide;
#[cfg(feature = "phosphor")]
pub mod phosphor;
pub mod semantic;
#[cfg(feature = "tabler")]
pub mod tabler;

pub use icon::{Icon, IconData, IconStyle};
